private Type determineInferredType() {
    if (this.method == null) {
        return null;
    }

    Type genericParameterType = null;
    boolean foundPayload = false;

    for (int i = 0; i < this.method.getParameterCount(); i++) {
        MethodParameter methodParameter = new MethodParameter(this.method, i);
        boolean isHeader = methodParameter.hasParameterAnnotation(Header.class);
        boolean isPayload = methodParameter.hasParameterAnnotation(Payload.class);

        if (isHeader && isPayload) {
            if (MessagingMessageListenerAdapter.this.logger.isWarnEnabled()) {
                MessagingMessageListenerAdapter.this.logger.warn(this.method.getName()
                        + ": Cannot annotate a parameter with both @Header and @Payload; "
                        + "ignored for payload conversion");
            }
        }

        if (isEligibleParameter(methodParameter) && (isPayload || !foundPayload)) {
            foundPayload = true;

            if (genericParameterType == null) {
                genericParameterType = extractGenericParameterTypeFromMethodParameter(methodParameter);
            } else {
                if (MessagingMessageListenerAdapter.this.logger.isDebugEnabled()) {
                    MessagingMessageListenerAdapter.this.logger.debug("Ambiguous parameters for target payload for method "
                            + this.method + "; no inferred type header added");
                }
                return null;
            }
        }
    }

    return genericParameterType;
}

